set -e  # Exit on error
set -u  # Exit on undefined variable

# Default LOG_FILE (overridden by process_arguments if retention > 0)
: "${LOG_FILE:=/dev/null}"

# Commands that can run without an initialized database.
# batch, database, environment and comment: the lines bootstrap's init spawns (its runner, database dir ensure,
# environment install, the checks' comment lines) before the .env layer exists.
COMMANDS_WITHOUT_DATABASE="help bootstrap init batch database environment log comment error fail complete"

#-----------------------------------------------------------------------------
# Environment Configuration
#-----------------------------------------------------------------------------

# Script path (for sourcing/re-exec in isolated environments).
: "${VM_BAKE_CONTEXT_SCRIPT:=$(readlink -f "$0" 2>>"$LOG_FILE" || realpath "$0" 2>>"$LOG_FILE" || echo "$0")}"

# Exit-code bits (propagated through the call tree).
: "${VM_BAKE_CONTEXT_EXIT_BITS:=0}"

# Was VM_BAKE_BASE explicitly set (before applying the default)?
VM_BAKE_BASE_EXPLICIT="${VM_BAKE_BASE:-}"

# Base directory for the ACTIVE database (the `db` symlink by default).
: "${VM_BAKE_BASE:=$HOME/.vm-bake/db}"

# Root holding all databases; `db` is a symlink here to the active DB (e.g.
# db -> current), so multiple DBs live side by side. Derived from VM_BAKE_BASE
# — which is passed through the env- re-exec, where $HOME is unset.
: "${VM_BAKE_ROOT:=$(dirname "$VM_BAKE_BASE")}"

# Environment directory (layered .env store lives here).
: "${VM_BAKE_ENV_DIR:=${VM_BAKE_BASE}/.env}"

# Library directory: contains include/ and template/. Default: script location.
: "${VM_BAKE_LIBDIR:=$(dirname "$VM_BAKE_CONTEXT_SCRIPT")}"

# Template directory: environment/ (and, later, image/upstream/snapshot helpers).
: "${VM_BAKE_TEMPLATE_DIR:=$VM_BAKE_LIBDIR/template}"

# The dump FORMAT this vm-bake writes and restores (the major version of the
# command vocabulary a dump carries; bump when it changes incompatibly).
# 'vm-bake version' prints it with the commit of this checkout.
VM_BAKE_FORMAT=1

# Directory configuration for database init/validation.
# Format: path:mode:exec_flag:content_policy (newline separated), relative to
# $VM_BAKE_BASE.
#   exec_flag:      "exec" (scripts must run) | "noexec" (safe for noexec mount)
#   content_policy: "exclusive" (must be empty) | "operational" (idempotent)
VM_BAKE_INIT_DIR_CONFIG=".tmp:0750:noexec:operational
.tmp/batch-exits:0750:noexec:operational
.log:0750:noexec:operational
.env:0700:noexec:operational
.env/default:0700:noexec:operational
.env/local:0700:noexec:operational
.templates:0700:noexec:operational
template:0700:noexec:operational
export:0700:noexec:operational"


#-----------------------------------------------------------------------------
# Platform commands (FreeBSD, inlined)
#-----------------------------------------------------------------------------
# vpn-switch loaded these from template/platform/<os>.sh. vm-bake targets
# FreeBSD only, so the handful the engine/database actually use are inlined
# here. EXAMINE_* = read-only inspection; MODIFY_* = state-changing.
CMD_STAT_PERMS='stat -f %Lp'       # file permissions (octal, e.g. 0400)
EXAMINE_FILE_OWNER='stat -f %u:%g' # file owner (uid:gid)
MODIFY_DIR_CREATE='mkdir -p'   # create directory (with parents)
MODIFY_FILE_PERMS='chmod'      # change file permissions
MODIFY_FILE_OWNER='chown'      # change file owner (uid:gid)
MODIFY_FILE_REMOVE='rm -f'     # remove file
MODIFY_FILE_COPY_FORCE='cp -f' # copy file (force overwrite)
MODIFY_LINK_FORCE='ln -sfn'    # force create/overwrite symlink

# Preserve the caller's ORIGINAL stdin as fd 3: the generator deliberately
# runs with stdin closed (dispatch </dev/null — nested batch pipelines must
# not eat each other's emissions), so the stdin-consuming argument forms
# ('add -') read from fd 3 instead. Dumps never replay the '-' form (they
# emit the expanded adds), so replays stay unaffected. Only the TOP-LEVEL
# call binds it: a re-invoked child (combinator interpreter) has the
# emission pipe as stdin and inherits fd 3 from its parent, so 'add -'
# works through a combinator too.
[ -n "${VM_BAKE_CONTEXT_BOOTSTRAPPED:-}" ] || exec 3<&0 || true

#-----------------------------------------------------------------------------
# Load the engine and the domain modules
#-----------------------------------------------------------------------------
. "$VM_BAKE_LIBDIR/include/engine.sh"
# Module preload is DATA (VM_BAKE_INCLUDES). Built-in minimal default: only
# the no-DB commands (bootstrap -> database.sh, help -> help.sh); every other
# module is lazy-loaded per dispatch via FUNCTION_MODULES. A bootstrapped DB
# preloads the full list from the VM_BAKE_INCLUDES template instead.
: "${VM_BAKE_INCLUDES:=database.sh help.sh}"
for _m in $VM_BAKE_INCLUDES; do
  test -f "$VM_BAKE_LIBDIR/include/$_m" || continue
  . "$VM_BAKE_LIBDIR/include/$_m"
done
unset _m

#-----------------------------------------------------------------------------
# Entry point
#-----------------------------------------------------------------------------
# Run main only when executed directly (not when sourced by a test harness).
if [ "${0##*/}" = "vm-bake.sh" ] || [ "${0##*/}" = "vm-bake" ]; then
  # A consumer that closes the pipe early (vm-bake ... | grep -q) must never kill a step
  # half-way: SIGPIPE is ignored (inherited by every interpreter), so a write to the closed
  # pipe fails as a write error and the emitted script reaches its own exit code. The
  # catchable signals end vm-bake with a plain failure: a killed batch runner must never
  # exit with 128+signum, which its parent would read as a pointer into the batch ring.
  trap '' PIPE
  trap 'exit 1' HUP INT QUIT TERM
  # Bootstrap: load environment from .env files exactly once, then re-exec.
  if [ -z "${VM_BAKE_CONTEXT_BOOTSTRAPPED:-}" ]; then
    env_args=$(build_env_args)

    # Provide interpreter defaults if .env files don't exist yet (first init).
    ensure_interpreter_var "VM_BAKE_TERMINAL_INTERPRETER"
    ensure_interpreter_var "VM_BAKE_COMBINATOR_INTERPRETER"
    ensure_interpreter_var "VM_BAKE_BATCH_COMBINATOR_INTERPRETER"

    passthrough=""
    passthrough="$passthrough VM_BAKE_CONTEXT_BOOTSTRAPPED=1"

    if [ -z "${VM_BAKE_CACHE_ENV_ARGS:-}" ]; then
      VM_BAKE_CACHE_ENV_ARGS="$env_args"
    fi
    passthrough="$passthrough VM_BAKE_CACHE_ENV_ARGS=\"\$VM_BAKE_CACHE_ENV_ARGS\""

    if [ -n "${VM_BAKE_TRACE_FILE:-}" ]; then
      case "$VM_BAKE_TRACE_FILE" in
        /*)
          passthrough="$passthrough VM_BAKE_TRACE_FILE=\"\$VM_BAKE_TRACE_FILE\""
          ;;
        *)
          VM_BAKE_TRACE_FILE="${VM_BAKE_BASE}/.trace/${VM_BAKE_TRACE_FILE}"
          passthrough="$passthrough VM_BAKE_TRACE_FILE=\"\$VM_BAKE_TRACE_FILE\""
          ;;
      esac
    fi

    if [ -n "${VM_BAKE_TRACE_DEPTH:-}" ]; then
      passthrough="$passthrough VM_BAKE_TRACE_DEPTH=\"\$VM_BAKE_TRACE_DEPTH\""
    fi

    if [ -n "${VM_BAKE_BATCH_KEEP_GOING:-}" ]; then
      passthrough="$passthrough VM_BAKE_BATCH_KEEP_GOING=\"$VM_BAKE_BATCH_KEEP_GOING\""
    fi

    # TERM for the owner's terminals (pinentry of attest, the hidden reads): a
    # gpg-agent first started from a cleaned environment without it keeps a
    # screen "too small" for every later signing
    if [ -n "${TERM:-}" ]; then
      passthrough="$passthrough TERM=\"\$TERM\""
    fi

    # Re-exec with the loaded environment.
    # VM_BAKE_BASE must come AFTER $env_args to override any .env value.
    eval "exec env - $env_args $passthrough VM_BAKE_CONTEXT_SCRIPT=\"\$VM_BAKE_CONTEXT_SCRIPT\" VM_BAKE_BASE=\"\$VM_BAKE_BASE\" \"\$VM_BAKE_CONTEXT_SCRIPT\" \"\$@\""
  fi

  # Bootstrapped: environment is loaded.
  main "$@"
fi
